import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.CqtftVNu.js";const p=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/upgrading.md","filePath":"guide/deployment/upgrading.md"}'),r={name:"guide/deployment/upgrading.md"};function n(s,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>This page collects <strong>action-required</strong> notes for upgrading an existing deployment. Entries are grouped by release, newest first. Routine changes (features, fixes) live in the <a href="https://github.com/authup/authup/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>; anything listed here either requires operator action or deliberately changes behavior.</p><h2 id="next-release-after-v1-0-0-beta-51" tabindex="-1">Next release (after v1.0.0-beta.51) <a class="header-anchor" href="#next-release-after-v1-0-0-beta-51" aria-label="Permalink to &quot;Next release (after v1.0.0-beta.51)&quot;">​</a></h2><h3 id="login-redirect-allowlist-—-set-trusted-origins" tabindex="-1">Login redirect allowlist — set <code>TRUSTED_ORIGINS</code> <a class="header-anchor" href="#login-redirect-allowlist-—-set-trusted-origins" aria-label="Permalink to &quot;Login redirect allowlist — set `TRUSTED_ORIGINS`&quot;">​</a></h3><p>Interactive login runs through the authorization-code flow against a per-realm <code>web</code> client whose redirect allowlist is built from the origin of <code>PUBLIC_URL</code> plus every entry in <code>TRUSTED_ORIGINS</code> (renamed from <code>ADDITIONAL_DOMAINS</code>).</p><p><strong>If your web UI is served from a different origin than <code>PUBLIC_URL</code></strong> (e.g. UI on <code>https://app.example.com</code>, server on <code>https://auth.example.com</code>) <strong>you must set</strong>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRUSTED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.example.com</span></span></code></pre></div><p>Otherwise every login fails after the redirect with an opaque OAuth2 error. Entries may be bare hosts (expanded to both <code>http</code> and <code>https</code>) or full origins; comma-separated.</p><div class="warning custom-block"><p class="custom-block-title">Security</p><p>Each trusted origin is added to a <code>builtIn</code> (auto-consent) client carrying the <code>global</code> scope — an allowlisted origin can obtain full-permission user tokens. Only list origins you control.</p></div><h3 id="refresh-token-rotation-hard-cutover" tabindex="-1">Refresh-token rotation (hard cutover) <a class="header-anchor" href="#refresh-token-rotation-hard-cutover" aria-label="Permalink to &quot;Refresh-token rotation (hard cutover)&quot;">​</a></h3><p>Every <code>refresh_token</code> grant now rotates: the presented token is retired and a fresh pair is issued. Refresh tokens minted <strong>before</strong> the upgrade are rejected with <code>invalid_grant</code> — active users have to sign in once after the upgrade. Replaying an already-consumed refresh token revokes the whole session family (RFC 6819 §5.2.2.3). A multi-tab tolerance window can be configured via <code>TOKEN_REFRESH_GRACE_PERIOD</code> (seconds, default <code>0</code> = strict).</p><h3 id="access-token-ttl-default-lowered-3600-→-900-seconds" tabindex="-1">Access-token TTL default lowered: 3600 → 900 seconds <a class="header-anchor" href="#access-token-ttl-default-lowered-3600-→-900-seconds" aria-label="Permalink to &quot;Access-token TTL default lowered: 3600 → 900 seconds&quot;">​</a></h3><p>Shrinks the revocation blind spot for stateless JWKS-verifying adapters. Override via <code>TOKEN_ACCESS_MAX_AGE</code> (seconds) if your deployment depends on longer-lived access tokens.</p><h3 id="authorize-token-flows-are-realm-bound" tabindex="-1">Authorize &amp; token flows are realm-bound <a class="header-anchor" href="#authorize-token-flows-are-realm-bound" aria-label="Permalink to &quot;Authorize &amp; token flows are realm-bound&quot;">​</a></h3><p>An identity can only authorize (or redeem a code / refresh a token) against a client in <strong>its own realm</strong> — a cross-realm attempt yields <code>login_required</code> / <code>invalid_grant</code>. Consequences:</p><ul><li>Master-realm admins can no longer sign into other realms&#39; applications through the built-in <code>web</code> client; use an identity of the target realm.</li><li>A client identified <strong>by name</strong> at <code>/authorize</code> now requires a realm hint (<code>realm_id</code>), since every realm has a <code>web</code> client.</li></ul><h3 id="implicit-hybrid-response-types-removed" tabindex="-1">Implicit &amp; hybrid response types removed <a class="header-anchor" href="#implicit-hybrid-response-types-removed" aria-label="Permalink to &quot;Implicit &amp; hybrid response types removed&quot;">​</a></h3><p><code>response_type=code</code> is the only supported response type (OAuth 2.1 posture). Public clients must use PKCE and <code>state</code> unconditionally; the <code>id_token</code> is minted at the <code>/token</code> exchange. RPs still using <code>token</code> / <code>id_token</code> / hybrid response types must migrate to the code flow.</p><h3 id="rp-initiated-logout-discovery-corrections" tabindex="-1">RP-initiated logout &amp; discovery corrections <a class="header-anchor" href="#rp-initiated-logout-discovery-corrections" aria-label="Permalink to &quot;RP-initiated logout &amp; discovery corrections&quot;">​</a></h3><ul><li>New <code>end_session_endpoint</code>: <code>GET/POST /logout</code> (advertised in the realm discovery document). Downstream apps should end the shared authup session by redirecting there with an <code>id_token_hint</code>.</li><li><code>post_logout_redirect_uri</code> is honored only when it matches the client&#39;s <strong>new, separate</strong><code>post_logout_redirect_uri</code> column — a URI matching only the login <code>redirect_uri</code> is rejected. Set the column for clients that use post-logout redirects (the provisioned <code>web</code> client is populated automatically).</li><li>Discovery <code>revocation_endpoint</code> was corrected from <code>…/token</code> to <code>…/token/revoke</code> (RFC 7009).</li></ul><h3 id="minimum-password-length-raised-to-10" tabindex="-1">Minimum password length raised to 10 <a class="header-anchor" href="#minimum-password-length-raised-to-10" aria-label="Permalink to &quot;Minimum password length raised to 10&quot;">​</a></h3><p>New password writes (user create/update, registration, password reset) reject values shorter than 10 characters — configurable via <code>PASSWORD_MIN_LENGTH</code>. Existing password hashes keep verifying; nobody is forced to reset. File-provisioned users whose configured password is shorter than the floor now fail provisioning validation at startup.</p><h3 id="client-granttypes-is-now-enforced" tabindex="-1"><code>Client.grantTypes</code> is now enforced <a class="header-anchor" href="#client-granttypes-is-now-enforced" aria-label="Permalink to &quot;`Client.grantTypes` is now enforced&quot;">​</a></h3><p>A non-null <code>grantTypes</code> value (space- or comma-delimited) acts as an allowlist at the <code>/token</code> grants and the <code>/authorize</code> code request; violations fail with <code>unauthorized_client</code>. <code>null</code> keeps allow-all semantics, so only clients that <em>set</em> the column are affected — review clients that stored decorative values (e.g. a client listing only <code>authorization_code</code> will fail token refreshes until <code>refresh_token</code> is added). The provisioned per-realm <code>web</code> client already lists <code>authorization_code refresh_token</code>.</p><h3 id="also-notable-no-action-required" tabindex="-1">Also notable (no action required) <a class="header-anchor" href="#also-notable-no-action-required" aria-label="Permalink to &quot;Also notable (no action required)&quot;">​</a></h3><ul><li><strong>Session management</strong>: <code>GET/DELETE /sessions</code> API plus a sessions UI (&quot;This device&quot; marker, &quot;log out other devices&quot;, admin force-logout).</li><li><strong>OIDC prompt surface</strong>: <code>/authorize</code> supports <code>prompt</code> (<code>none|login|consent|select_account</code>), <code>max_age</code> and <code>login_hint</code>; the <code>@authup/client-web-kit</code> URL builder now defaults to <code>prompt=select_account</code>, so kit-based apps inherit an account chooser on lingering sessions (pass an explicit <code>prompt</code> to opt out).</li><li><strong>id_token claims</strong>: <code>auth_time</code> now reflects the real authentication instant and a <code>sid</code> (session id) claim is included.</li></ul>',26)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
